                        "content": "Sur n'importe quelle page de détails d'un anime, cherche l'icône en forme de cœur en haut à droite (ou juste sous l'image d'en-tête). Touche-la pour ajouter ou retirer l'anime de tes « Favoris ». Tu peux voir tous tes favoris sur ta page Profil."
