            "lastUpdated": "Ultimo aggiornamento: 22 dicembre 2025",
            "intro": "L'uso di questa applicazione è regolato dal Contratto di licenza standard per l'utente finale (EULA) di Apple. Inoltre, leggi questi Termini, che riguardano nello specifico il tuo account e i tuoi contenuti.",
