                    "title": "1. Accettazione dei Termini",
                    "content": "Accedendo al Servizio o utilizzandolo, accetti di essere vincolato da questi Termini. Se non sei d'accordo con una qualsiasi parte dei termini, non puoi accedere al Servizio."
